/* Lot 91: values against @property syntaxes with alternatives and lists (generated by scripts/lot91_propgen.py; expectations from that model). */

#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssprop.h"

static wf_cssprop_t g_p;

static int m(const char *syn, const char *v) {
    memset(&g_p, 0, sizeof(g_p));
    g_p.syntax = (unsigned char)wf_cssprop_syntax_parse(syn, (int)strlen(syn), &g_p);
    if (g_p.syntax == 0) return -1;
    return wf_cssprop_match_prop(&g_p, v);
}

static void test_l91_match_0(void) {
    TEST_ASSERT_EQUAL(1, m("'auto | red# | small# | -moz-thing#'", "small"));
    TEST_ASSERT_EQUAL(1, m("'<color> | <custom-ident> | left-side'", "small"));
    TEST_ASSERT_EQUAL(1, m("'<length> | <length-percentage>'", "max((  3.6ch))"));
    TEST_ASSERT_EQUAL(0, m("'thin | <number>#'", "44.3s"));
    TEST_ASSERT_EQUAL(1, m("'<angle>'", "calc( 196grad 	+ 31.2deg )"));
    TEST_ASSERT_EQUAL(1, m("'red | <length> | <number>#'", "37.9mm"));
}

